do $verify$ begin
 if (select count(*) from public.theories where status='published')<>794 then raise exception 'Published count mismatch';end if;
 if (select count(*) from public.theories)<>799 then raise exception 'Physical count mismatch';end if;
 if (select count(*) from public.theories where status='published' and access_tier='free')<>151 then raise exception 'Free tier changed';end if;
 if exists(select 1 from public.theories t left join public.theory_subcategories s on s.id=t.subcategory_id where t.status='published' and (s.id is null or s.category_id<>t.category_id or t.taxonomy_order is null)) then raise exception 'Unclassified theory';end if;
 if exists(select 1 from public.theories where status='published' group by category_id,display_id having count(*)>1) then raise exception 'Display ID collision';end if;
 if exists(select 1 from public.theories where status='published' group by subcategory_id,taxonomy_order having count(*)>1) then raise exception 'Taxonomy order collision';end if;
 if exists(select 1 from public.theories t where t.id ~ '^kb_(869|8[7-9][0-9]|90[0-8])$' and not exists(select 1 from public.paid_content p where p.content_type='theory' and p.content_id=t.id and p.payload->>'summary'=t.summary and p.payload->>'subcategoryId'=t.subcategory_id)) then raise exception 'Paid projection mismatch';end if;
end $verify$;
